    #[test]
    fn source_validation_shell_function_probes_extensionless_archives() {
        let shell = source_validation_shell_function();

        assert!(shell.contains("gzip -t \"$source_path\" >/dev/null 2>&1 && tar -tzf \"$source_path\" >/dev/null 2>&1; then return 0; fi"));
        assert!(shell.contains("if command -v tar >/dev/null 2>&1 && tar -tf \"$source_path\" >/dev/null 2>&1; then return 0; fi"));
        assert!(shell.contains("*.zip|*.jar)"));
        assert!(shell.contains(
            "if command -v unzip >/dev/null 2>&1 && UNZIP_DISABLE_ZIPBOMB_DETECTION=TRUE unzip -tqq \"$source_path\" >/dev/null 2>&1; then return 0; fi"
        ));
        assert!(shell.contains("od -An -tx1 -N4 \"$source_path\""));
        assert!(shell.contains("grep -q '^#!'"));
        assert!(
            shell.contains("<!doctype html|<html|<head|<body|not found|access denied|rate limit")
        );
        assert!(
            shell.contains(
                "file -b \"$source_path\" | grep -Eqi 'ELF|script|executable|source|text'"
            )
        );
        assert!(shell.contains("return 1"));
    }

