    #[test]
    fn harden_build_script_creates_prefix_bin_for_symlink_installs() {
        let hardened = harden_build_script_text(
            "ln -sf $gem_path/bin/* $PREFIX/bin\nln -sfn \"$tool_dir/bin/tool\" \"${PREFIX}/bin\"\n",
        );
        assert!(hardened.contains(
            "mkdir -p $PREFIX/bin\nln -sf $gem_path/bin/* $PREFIX/bin\nexport PATH=\"$PREFIX/bin:$PATH\""
        ));
        assert!(
            hardened.contains(
                "mkdir -p ${PREFIX}/bin\nln -sfn \"$tool_dir/bin/tool\" \"${PREFIX}/bin\"\nexport PATH=\"${PREFIX}/bin:$PATH\""
            )
        );
    }

    #[test]
    fn minimal_interpreter_keeps_prefix_alias_installs_in_install_phase() {
        let script = r#"
PACKAGE_HOME="${PREFIX}/share/${PKG_NAME}-${PKG_VERSION}-${PKG_BUILDNUM}"
mkdir -p "${PACKAGE_HOME}"
cp -f comparem2 LICENSE "${PACKAGE_HOME}"
BIN=${PREFIX}/bin
cp dupsifter ${BIN}
"#;
        let plan = interpret_build_script_minimal(script);

        assert!(
            plan.install_commands
                .iter()
                .any(|line| line.contains("cp -f comparem2 LICENSE"))
        );
        assert!(
            plan.install_commands
                .iter()
                .any(|line| line.contains("cp dupsifter ${BIN}"))
        );
        assert!(
            !plan
                .build_commands
                .iter()
                .any(|line| line.contains("cp -f comparem2 LICENSE"))
        );
        assert!(
            !plan
                .build_commands
                .iter()
                .any(|line| line.contains("cp dupsifter ${BIN}"))
        );
    }

    #[test]
    fn symlink_detection_handles_permuted_ln_options() {
        assert!(command_mentions_symlink_install(&[
            "ln -fs $GORPIPEDIR/bin/gorpipe $PREFIX/bin/gorpipe".to_string()
        ]));
        assert!(command_mentions_symlink_install(&[
            "ln -snf target link".to_string()
        ]));
        assert!(command_mentions_symlink_install(&[
            "mkdir -p $PREFIX/bin && ln -s $PREFIX/share/tool.py $PREFIX/bin/tool".to_string()
        ]));
        assert!(!command_mentions_symlink_install(&[
            "ln target link".to_string()
        ]));
    }

