    #[test]
    fn incremental_build_report_updates_json_and_catalogue() {
        let unique = format!(
            "bioconda2rpm-incremental-report-{}-{}",
            std::process::id(),
            Utc::now().timestamp_nanos_opt().unwrap_or(0)
        );
        let topdir = std::env::temp_dir().join(unique);
        let report_json = topdir.join("targets/test-target/reports/build_batch_test.json");
        let entries = vec![ReportEntry {
            software: "adam".to_string(),
            priority: 0,
            status: "quarantined".to_string(),
            reason: "payload spec build failed in container".to_string(),
            overlap_recipe: "adam".to_string(),
            overlap_reason: "test".to_string(),
            variant_dir: String::new(),
            package_name: "adam".to_string(),
            version: "1.0.1".to_string(),
            payload_spec_path: String::new(),
            meta_spec_path: String::new(),
            staged_build_sh: String::new(),
        }];
        persist_incremental_build_report(&topdir, &entries, "x86_64", "test-target", &report_json);
        let payload = std::fs::read_to_string(&report_json).expect("read incremental report");
        let parsed: Vec<ReportEntry> = serde_json::from_str(&payload).expect("parse report");
        assert_eq!(parsed.len(), 1);
        let catalogue =
            std::fs::read_to_string(topdir.join(".catalog.json")).expect("read catalogue");
        assert!(catalogue.contains("adam"));
        let _ = std::fs::remove_dir_all(&topdir);
    }

    #[test]
    fn minimal_build_interpreter_splits_build_and_install_commands() {
        let script = r#"
#!/usr/bin/env bash
set -euxo pipefail
cmake -S . -B build
cmake --build build -j"${CPU_COUNT:-1}"
cmake --install build --prefix "$PREFIX"
"#;
        let plan = interpret_build_script_minimal(script);
        assert!(
            plan.build_commands
                .iter()
                .any(|c| c.contains("cmake -S . -B build"))
        );
        assert!(
            plan.build_commands
                .iter()
                .any(|c| c.contains("cmake --build build"))
        );
        assert!(
            plan.install_commands
                .iter()
                .any(|c| c.contains("cmake --install build"))
        );
    }

    #[test]
    fn minimal_build_interpreter_joins_continuations_and_drops_control_flow_bodies() {
        let script = r#"
#!/usr/bin/env bash
set -euxo pipefail
if [[ "$(uname)" == Darwin ]]; then
  export CONFIG_ARGS=""
fi
case "$(uname -m)" in
  aarch64) export CFLAGS="-O3" ;;
esac
cmake -S . -B build -DCMAKE_INSTALL_PREFIX="${PREFIX}" \
  -DZLIB_ROOT="${PREFIX}" \
  -DCMAKE_CXX_COMPILER="${CXX}" \
  "${CONFIG_ARGS}"
make install PREFIX="${PREFIX}"
"#;
        let plan = interpret_build_script_minimal(script);
        assert!(
            plan.build_commands
                .iter()
                .chain(plan.install_commands.iter())
                .any(|c| c.contains("-DCMAKE_CXX_COMPILER=\"${CXX}\""))
        );
        assert!(
            !plan
                .build_commands
                .iter()
                .any(|c| c.contains("CONFIG_ARGS=\"\"") || c.contains("aarch64)"))
        );
        assert!(
            plan.install_commands
                .iter()
                .any(|c| c.contains("make install PREFIX=\"${PREFIX}\""))
        );
    }

