    #[test]
    fn minimal_build_interpreter_keeps_treeswirl_cmake_before_ninja() {
        let script = r#"
export INCLUDES="-I${PREFIX}/include"
export LIBPATH="-L${PREFIX}/lib"
export LDFLAGS="${LDFLAGS} -L${PREFIX}/lib"
export CXXFLAGS="${CXXFLAGS} -O3 -I${PREFIX}/include"
cmake . -GNinja \
    -DCONDA=ON \
    -DCMAKE_BUILD_TYPE=Release \
    -DCMAKE_INSTALL_PREFIX="${PREFIX}" \
    -DCMAKE_CXX_COMPILER="${CXX}" \
    -DCMAKE_CXX_FLAGS="${CXXFLAGS}" \
    "${CONFIG_ARGS}"
ninja -v -j"${CPU_COUNT}" || exit 1
mkdir -p ${PREFIX}/bin
install -v -m 0755 TreeSwirl ${PREFIX}/bin || exit 1
"#;
        let plan = interpret_build_script_minimal(script);
        let cmake_index = plan
            .build_commands
            .iter()
            .position(|line| line.contains("cmake . -GNinja"))
            .expect("treeswirl cmake configure in build phase");
        let ninja_index = plan
            .build_commands
            .iter()
            .position(|line| line.contains("ninja -v"))
            .expect("treeswirl ninja in build phase");
        assert!(cmake_index < ninja_index);
        assert!(
            !plan
                .install_commands
                .iter()
                .any(|line| line.contains("cmake . -GNinja"))
        );
        assert!(
            plan.install_commands
                .iter()
                .any(|line| line.starts_with("install -v -m 0755 TreeSwirl"))
        );
    }

    #[test]
    fn minimal_build_interpreter_drops_diff_hunk_lines() {
        let script = r#"
--- src/old.c
+++ src/new.c
@@ -1,3 +1,5 @@
+    "${PREFIX}/ssl/cacert.pem",
cmake -S . -B build
"#;
        let plan = interpret_build_script_minimal(script);
        assert_eq!(
            plan.build_commands
                .iter()
                .filter(|line| line.contains("cmake -S . -B build"))
                .count(),
            1
        );
        assert!(
            !plan
                .build_commands
                .iter()
                .chain(plan.install_commands.iter())
                .any(|line| line.starts_with("--- ")
                    || line.starts_with("+++ ")
                    || line.starts_with("@@"))
        );
    }

    #[test]
    fn minimal_build_interpreter_preserves_multiline_bioconductor_makevars_write() {
        let script = r#"
#!/bin/bash
mv DESCRIPTION DESCRIPTION.old
grep -v '^Priority: ' DESCRIPTION.old > DESCRIPTION
mkdir -p ~/.R
echo -e "CC=$CC
FC=$FC
CXX=$CXX
CXX98=$CXX
CXX11=$CXX
CXX14=$CXX" > ~/.R/Makevars
$R CMD INSTALL --build .
"#;
        let plan = interpret_build_script_minimal(script);
        assert!(
            plan.build_commands
                .iter()
                .any(|line| line == "mv DESCRIPTION DESCRIPTION.old")
        );
        assert!(
            plan.build_commands
                .iter()
                .any(|line| line.contains("grep -v '^Priority: ' DESCRIPTION.old > DESCRIPTION"))
        );
        assert!(
            plan.build_commands
                .iter()
                .any(|line| line.contains("mkdir -p ~/.R"))
        );
        let makevars_write = plan
            .build_commands
            .iter()
            .find(|line| line.contains("> ~/.R/Makevars"))
            .expect("multiline Makevars write retained as one command");
        assert!(makevars_write.contains("echo -e \"CC=$CC\nFC=$FC\nCXX=$CXX"));
        assert!(makevars_write.contains("CXX14=$CXX\" > ~/.R/Makevars"));
        assert!(
            plan.install_commands
                .iter()
                .any(|line| line.contains("$R CMD INSTALL --build ."))
        );
        assert!(
            !plan
                .install_commands
                .iter()
                .any(|line| line.contains("> ~/.R/Makevars"))
        );
    }

